"""Generate the symmetric TDM warehouse. No BR/practice world is edited.

Run from any directory with py -3 scripts/gen_tdm_map.py.
The 81x65 arena has a solid roof: cover has no accessible upper surface.
"""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'data/oa/function/tdm/map'
OUT.mkdir(parents=True, exist_ok=True)
lines = [
    '# Generated by scripts/gen_tdm_map.py. Execute in oa:tdm only.',
    'execute unless dimension oa:tdm run return 0',
    'execute if score #active tdm.sys matches 1 run return 0',
    'forceload add -48 -48 47 47',
    'kill @e[tag=tdm.node]',
    'kill @e[tag=tdm.label]',
    'kill @e[tag=tdm.pickup]',
]
def fill(x1,y1,z1,x2,y2,z2,block):
    assert (x2-x1+1)*(y2-y1+1)*(z2-z1+1) <= 32768
    lines.append(f'fill {x1} {y1} {z1} {x2} {y2} {z2} minecraft:{block}')
for y in (60,64,68,72): fill(-42,y,-34,42,y+3,34,'air')
fill(-41,63,-33,41,63,33,'bedrock')
fill(-40,64,-32,40,64,32,'polished_andesite')
fill(-41,65,-33,-41,70,33,'polished_deepslate')
fill(41,65,-33,41,70,33,'polished_deepslate')
fill(-40,65,-33,40,70,-33,'polished_deepslate')
fill(-40,65,33,40,70,33,'polished_deepslate')
fill(-41,71,-33,41,71,33,'smooth_stone')
for z in (-24,-12,0,12,24):
    fill(-39,71,z,39,71,z,'sea_lantern')
# Three longitudinal lanes, with alternating cross-links. All cover meets the roof.
for x in (-24,-12,12,24):
    for z in (-16,16):
        fill(x-2,65,z-4,x+2,70,z+4,'stone_bricks')
        for side in (-1,1):
            fill(x-2,65,z+side*4,x+2,66,z+side*4,'chiseled_stone_bricks')
for x in (-10,10):
    fill(x-1,65,-3,x+1,70,3,'polished_deepslate')
for z in (-26,26):
    fill(-3,65,z-1,3,70,z+1,'stone_bricks')
# Offset blast walls protect spawn pockets without trapping players.
for side,color in ((-1,'red'),(1,'blue')):
    x=side*32
    fill(min(x-6,x+6),64,-30,max(x-6,x+6),64,30,f'{color}_concrete')
    for z in (-20,0,20):
        wall=side*28
        fill(wall-1,65,z-3,wall+1,70,z+3,'deepslate_bricks')
        lines.append(f'summon minecraft:text_display {side*37} 67 {z} '+json.dumps({'Tags':['tdm.label'],'text':{'text':'赤リスポーン' if side<0 else '青リスポーン','color':color},'billboard':'center','background':0},ensure_ascii=False,separators=(',',':')))
# Route stripes and center objective.
for z in (-8,8): fill(-27,64,z,27,64,z,'light_gray_concrete')
for z in (-8,8): fill(-4,64,z-1,4,64,z+1,'water')
fill(-3,64,-3,3,64,3,'cyan_concrete')
for slot,(x,z,typ,label) in enumerate([
    (-18,-8,0,'固有武器 / 30秒'),(18,8,0,'固有武器 / 30秒'),
    (-18,8,0,'固有武器 / 30秒'),(18,-8,0,'固有武器 / 30秒'),
    (-6,-20,101,'鉄防具強化 / 30秒'),(6,20,101,'鉄防具強化 / 30秒'),
    (0,0,102,'中央ダイヤ防具 / 60秒'),
],1):
    lines += [f'summon minecraft:marker {x} 65 {z} {{Tags:["tdm.node","tdm.new"]}}',
              f'scoreboard players set @e[tag=tdm.new] tdm.slot {slot}',
              f'scoreboard players set @e[tag=tdm.new] tdm.type {typ}',
              'tag @e[tag=tdm.new] remove tdm.new',
              f'summon minecraft:text_display {x} 67.2 {z} '+json.dumps({'Tags':['tdm.label'],'text':{'text':label,'color':'aqua' if typ==102 else 'yellow'},'billboard':'center','background':0},ensure_ascii=False,separators=(',',':'))]
lines += [
    'gamerule minecraft:immediate_respawn true',
    'gamerule minecraft:keep_inventory true',
    'gamerule minecraft:show_advancement_messages false',
    'gamerule minecraft:spawn_mobs false',
    'gamerule minecraft:mob_griefing false',
    'gamerule minecraft:fire_spread_radius_around_player 0',
    'gamerule minecraft:natural_health_regeneration true',
    'time set noon',
    'weather clear',
    'worldborder center 0 0',
    'worldborder set 86',
    'scoreboard players set #ready tdm.sys 0',
    'execute if block -40 64 -32 minecraft:polished_andesite if block 40 64 32 minecraft:polished_andesite if block 0 71 0 minecraft:sea_lantern run scoreboard players set #ready tdm.sys 1',
]
(OUT/'build.mcfunction').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(f'TDM arena: {len(lines)} commands, 7 pickup nodes, 81x65')
